/// AnalyticsService is Sylphx Analytics: one event stream per environment and
/// the same numbers for every customer (docs/specs/one-platform/analytics.md).
/// This contract writes events and reads them back; the daily stats and
/// retention methods are added with the store that computes them.
///
/// Namespace of Sylphx Analytics on the client.
pub struct AnalyticsApi<'a, T> {
    client: &'a crate::runtime::Client<T>,
}

impl<'a, T: crate::runtime::Transport> AnalyticsApi<'a, T> {
    /// The `analytics_events` collection.
    pub fn analytics_events(&self) -> AnalyticsEventsCollection<'a, T> {
        AnalyticsEventsCollection {
            client: self.client,
        }
    }
}

/// `analytics_events` of Sylphx Analytics: Resource type `analytics.sylphx.com/AnalyticsEvent`.
pub struct AnalyticsEventsCollection<'a, T> {
    client: &'a crate::runtime::Client<T>,
}

impl<'a, T: crate::runtime::Transport> AnalyticsEventsCollection<'a, T> {
    /// Records a batch of events. Each event is judged alone: a bad event is
    /// reported in `results` and the rest are stored. A duplicate `event_id`
    /// (in this or an earlier batch) is counted once. The response is sent only
    /// after the store holds the accepted events.
    ///
    /// `POST /v1/{parent=orgs/*/projects/*/envs/*}/analytics_events:batch` · permission `analytics:ingest` · effect `write`
    ///
    /// Errors: `UNAUTHENTICATED`, `PERMISSION_DENIED`, `INVALID_FIELD`, `RATE_LIMITED`.
    pub async fn batch(
        &self,
        request: BatchEventsRequest,
    ) -> Result<BatchEventsResponse, crate::runtime::Error> {
        let path = format!(
            "/v1/{}/analytics_events:batch",
            crate::runtime::path_param(&request.parent, "orgs/*/projects/*/envs/*", "parent")?
        );
        let query = crate::runtime::Query::default();
        let http = crate::runtime::HttpRequest {
            method: "POST",
            path,
            query: query.0,
            body: Some(crate::runtime::body_without(&request, &["parent"])?),
            mutation: true,
            origin: None,
            effect_ids: false,
        };
        self.client.call(http).await
    }

    /// Lists the environment's raw events in a time range, newest first.
    ///
    /// Unlike public ingest (`POST /v1/analytics/events:batch`), this route requires
    /// `service_enablements/analytics` to be enabled on the project.
    ///
    /// `GET /v1/{parent=orgs/*/projects/*/envs/*}/analytics_events` · permission `analytics:read` · effect `read`
    ///
    /// Errors: `UNAUTHENTICATED`, `PERMISSION_DENIED`, `INVALID_FIELD`, `PAGE_TOKEN_MISMATCH`.
    pub async fn list(
        &self,
        request: ListAnalyticsEventsRequest,
    ) -> Result<ListAnalyticsEventsResponse, crate::runtime::Error> {
        let path = format!(
            "/v1/{}/analytics_events",
            crate::runtime::path_param(&request.parent, "orgs/*/projects/*/envs/*", "parent")?
        );
        let mut query = crate::runtime::Query::default();
        query.push("start_time", &request.start_time);
        query.push("end_time", &request.end_time);
        query.push("event_name", &request.event_name);
        query.push("subject_id", &request.subject_id);
        query.push("page_size", &request.page_size);
        query.push("page_token", &request.page_token);
        let http = crate::runtime::HttpRequest {
            method: "GET",
            path,
            query: query.0,
            body: None,
            mutation: false,
            origin: None,
            effect_ids: false,
        };
        self.client.call(http).await
    }

    /// Every page of [`Self::list`], collected.
    pub async fn list_all(
        &self,
        mut request: ListAnalyticsEventsRequest,
    ) -> Result<Vec<AnalyticsEvent>, crate::runtime::Error> {
        let mut items = Vec::new();
        loop {
            let page = self.list(request.clone()).await?;
            items.extend(page.analytics_events);
            if page.next_page_token.is_empty() {
                return Ok(items);
            }
            request.page_token = page.next_page_token;
        }
    }

    /// Aggregates deduplicated events in the environment over a bounded interval.
    ///
    /// Unlike public ingest (`POST /v1/analytics/events:batch`), this route requires
    /// `service_enablements/analytics` to be enabled on the project.
    ///
    /// `POST /v1/{parent=orgs/*/projects/*/envs/*}/analytics_events:query` · permission `analytics:read` · effect `read`
    ///
    /// Errors: `UNAUTHENTICATED`, `PERMISSION_DENIED`, `INVALID_FIELD`, `UNAVAILABLE`.
    pub async fn query(
        &self,
        request: QueryAnalyticsEventsRequest,
    ) -> Result<QueryAnalyticsEventsResponse, crate::runtime::Error> {
        let path = format!(
            "/v1/{}/analytics_events:query",
            crate::runtime::path_param(&request.parent, "orgs/*/projects/*/envs/*", "parent")?
        );
        let query = crate::runtime::Query::default();
        let http = crate::runtime::HttpRequest {
            method: "POST",
            path,
            query: query.0,
            body: Some(crate::runtime::body_without(&request, &["parent"])?),
            mutation: true,
            origin: None,
            effect_ids: false,
        };
        self.client.call(http).await
    }
}
